import { Link, useNavigate } from "react-router-dom";
import axios from "axios";
import toast from "react-hot-toast";

function Add_delete() {
  const [user, setUser] = useState({
    name: "",
    class:"",
    roll: "",
    gender: "",
  });

  const navigate = useNavigate();

  // Handle input field changes
  const inputHandler = (e) => {
    const { name, value } = e.target;
    setUser({ ...user, [name]: value });
  };

  // Handle form submit
  const submitForm = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post("http://localhost:8000/api/user", user);
      toast.success(response.data.message || "User added successfully", {
        position: "top-right",
      });
      setUser({ name: "", email: "", address: "" }); // reset fields
    } catch (error) {
      console.error("❌ Error adding user:", error);
      toast.error("Failed to add user");
    }
  };

  return (
    <div className="addUser" style={{ padding: "20px" }}>
      <Link to="/Teacherdashboard" type="button" className="btn btn-secondary mb-3">
        <i className="fa-solid fa-backward"></i> Back
      </Link>

      <h3>Add New User</h3>
      <form className="addUserForm" onSubmit={submitForm}>
        <div className="inputGroup mb-3">
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            value={user.name}
            onChange={inputHandler}
            name="name"
            autoComplete="off"
            placeholder="Enter your Name"
            required
          />
        </div>

        <div className="inputGroup mb-3">
          <label htmlFor="class">class:</label>
   
<select name='class' onChange={inputHandler} value={user.class}>
  <option value="">-- Select an Class --</option>
  <option value="10">10</option>
  <option value="9"> 9</option>
  <option value="8">8</option>
  <option value="7">7</option>
</select>
        </div>

        <div className="inputGroup mb-3">
          <label htmlFor="roll">roll:</label>
          <input
            type="text"
            id="address"
            value={user.roll}
            onChange={inputHandler}
            name="roll"
            placeholder="Enter the roll number"
            required
          />
        </div>
 <div className="inputGroup mb-3">
          <label htmlFor="address">gender:</label>
    
<select name='gender' onChange={inputHandler} value={user.gender}>
  <option value="">-- Select the gender --</option>
  <option value="male">male</option>
  <option value="female"> female</option>
  <option value="other">other</option> 
</select>
        </div>

        <div className="inputGroup">
          <button type="submit" className="btn btn-primary">
            Submit
          </button>
        </div>
      </form>
    </div>
  );
}

export default Add_delete;
